let out = 'no';
if (se.processes.whose({name: 'Safari'}).length) {
  const proc = se.processes.byName('Safari');
  if (proc.windows.length) {
    const queue = [proc.windows[0]]; let seen = 0;
    while (queue.length && seen < 2500) {
      const el = queue.shift(); seen += 1;
      try {
        if (el.role() === 'AXButton') {
          const label = [el.description(), el.name(), el.title()].join(' ');
          if (/^\s*pause\b/i.test(label)) { out = 'yes'; break; }
        }
      } catch (e) {}
      try { for (const child of el.uiElements()) queue.push(child); } catch (e) {}
    }
  }
}
